from google.cloud import secretmanager
from pydantic import BaseModel

from datahub.secret.secret_store import SecretStore

logger = logging.getLogger(__name__)


class GcpSecretManagerStoreConfig(BaseModel):
    project_id: str
    prefix: str = ""
    # TTL (in seconds) for the in-memory cache of resolved secret values.
    cache_ttl: int = 300


# SecretStore implementation that resolves secrets from Google Cloud Secret
# Manager. Resource paths are constructed from the configured project_id and
# prefix, so callers reference secrets by their unprefixed logical name.
class GcpSecretManagerStore(SecretStore):
    def __init__(self, config: GcpSecretManagerStoreConfig) -> None:
        self.config = config
        self.project_id = config.project_id
        self.prefix = config.prefix
        self.client = secretmanager.SecretManagerServiceClient()
        self._retry = Retry()
        self._cache: TTLCache = TTLCache(maxsize=1024, ttl=config.cache_ttl)

    def get_secret_value(self, secret_name: str) -> Optional[str]:
        if secret_name in self._cache:
            return self._cache[secret_name]

        name = (
            f"projects/{self.project_id}/secrets/"
            f"{self.prefix}{secret_name}/versions/latest"
        )
        try:
            response = self.client.access_secret_version(
                request={"name": name},
                retry=self._retry,
            )
            secret_value = response.payload.data.decode("UTF-8")
        except Exception:
            # A missing secret (or any resolution failure) is not fatal; the
            # framework treats unresolved secrets as None.
            logger.debug(
                f"Unable to resolve secret '{name}' from GCP Secret Manager.",
                exc_info=True,
            )
            return None

        self._cache[secret_name] = secret_value
        return secret_value

    def get_secret_values(self, secret_names: List[str]) -> Dict[str, Optional[str]]:
        return {
            secret_name: self.get_secret_value(secret_name)
            for secret_name in secret_names
        }

    def get_id(self) -> str:
        return "gcp-sm"

    def close(self) -> None:
        return

    @classmethod
    def create(cls, config: Any) -> "GcpSecretManagerStore":
        config = GcpSecretManagerStoreConfig.model_validate(config)
        return cls(config)
